// Discover native WhatsApp one-off campaigns, not EspoCRM campaigns. No manually entered IDs.
// This is READ-ONLY. Reconcile the most recent completed campaigns first; never silently invent links.
const all=$input.all().map(x=>x.json).filter(x=>x&&Object.keys(x).length);
const eligible=all.filter(c=>c.campaign_type==='one_off' && c.inbox?.channel_type==='Channel::Whatsapp' && c.campaign_status==='completed');
eligible.sort((a,b)=>(Number(b.completed_at)||0)-(Number(a.completed_at)||0)||Number(b.id)-Number(a.id));
const MAX_CAMPAIGNS=40;
if(eligible.length>MAX_CAMPAIGNS)throw new Error('SAFE_SCAN_LIMIT_EXCEEDED: '+eligible.length+' completed WhatsApp campaigns; expand pagination/ledger before full automatic reporting');
if(!eligible.length)return [{json:{hasCampaign:false,reason:'NO_COMPLETED_NATIVE_WHATSAPP_CAMPAIGNS',chatwootCampaignsDiscovered:all.length}}];
const ids=new Set();
return eligible.map(c=>{
 const id=Number(c.id);
 if(!Number.isSafeInteger(id)||id<=0||ids.has(id))throw new Error('Invalid/duplicate Chatwoot native campaign display ID');
 ids.add(id);
 return {json:{hasCampaign:true,chatwootCampaignId:id,title:typeof c.title==='string'?c.title.slice(0,120):'',
      completedAt:c.completed_at??null,inboxId:c.inbox?.id??null,readOnly:true}};
});

// Each Chatwoot community-node recipient result carries pairedItem index pointing
// to the Get Metrics input campaign. Never guess recipient-to-campaign association.
const selections=$('Select Completed WhatsApp Campaigns').all().map(x=>x.json).filter(x=>x.hasCampaign===true);
const metricsRows=$('Chatwoot - Get Metrics For Each Campaign').all();
const metricsByIdx=new Map(),recipientByIdx=new Map();
function pairedIndex(item,label){
 const p=Array.isArray(item.pairedItem)?item.pairedItem[0]:item.pairedItem;
 if(!p||!Number.isInteger(p.item)||p.item<0)throw new Error('MISSING_PAIRING_'+label+': refusing to mix unrelated campaigns');
 return p.item;
}
for(const row of metricsRows){
 const idx=pairedIndex(row,'METRICS');
 if(idx>=selections.length||metricsByIdx.has(idx))throw new Error('Duplicate/unmatched campaign metrics');
 metricsByIdx.set(idx,row.json);
}
for(const row of $input.all()){
 if(!row.json||Object.keys(row.json).length===0)continue;
 const idx=pairedIndex(row,'RECIPIENT');
 if(idx>=selections.length||!metricsByIdx.has(idx))throw new Error('Unmatched recipient campaign ID');
 if(!recipientByIdx.has(idx))recipientByIdx.set(idx,[]);
 recipientByIdx.get(idx).push(row.json);
}
const final=[];
for(let idx=0;idx<selections.length;idx++){
 const c=selections[idx],m=metricsByIdx.get(idx),rows=recipientByIdx.get(idx)||[];
 if(!m||!Number.isInteger(m.audience))throw new Error('Missing valid campaign metrics');
 const counts={queued:0,skipped:0,sent:0,delivered:0,read:0,failed:0},codes={},seen=new Set();
 for(const row of rows){
  const recipientId=Number(row?.contact?.id);
  if(!Number.isSafeInteger(recipientId)||recipientId<=0||seen.has(recipientId)||!Object.hasOwn(counts,row.status))
    throw new Error('Invalid/duplicate recipient in campaign '+c.chatwootCampaignId);
  seen.add(recipientId);counts[row.status]++;
  if(row.status==='failed'){
   const code=row.error_code===null||row.error_code===undefined?'UNKNOWN':String(row.error_code);
   if(!/^(UNKNOWN|[0-9]{3,8})$/.test(code))throw new Error('Unexpected failure-code format');
   codes[code]=(codes[code]||0)+1;
  }
 }
 if(seen.size!==m.audience||counts.read!==m.read||counts.delivered+counts.read!==m.delivered||
    counts.failed!==m.failed||counts.skipped!==m.skipped)
   throw new Error('Analytics count mismatch for campaign '+c.chatwootCampaignId+'; retry a later run');
 final.push({chatwootCampaignId:c.chatwootCampaignId,title:c.title,
   audience:m.audience,counts,deliveredIncludingRead:counts.delivered+counts.read,
   errorCodeCounts:codes,matchedEspoCampaignId:null,verifiedCrmMapping:false});
}
return [{json:{checkedAt:new Date().toISOString(),mode:'READ_ONLY',autoDiscoverCampaigns:true,
 campaignCount:final.length,reports:final,crmEventWriteAuthorized:false,
 note:'Chatwoot reports only; EspoCRM campaign/recipient association needs a verified batch ledger.'}}];
